// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Load Oswald font at module level for reliable rendering on Lambda
const { fontFamily: oswaldFamily } = loadOswald();

// Helper to generate the custom ticket path with cutouts on the sides
const getTicketPath = (w: number, h: number, r: number, inset: number) => {
  const left = inset;
  const right = w - inset;
  const top = inset;
  const bottom = h - inset;
  const cy = h / 2; // Vertical center of the cutout

  // Drawing the path with top-left, right cutout, bottom-right, bottom-left, left cutout
  return `
    M ${left}, ${top}
    L ${right}, ${top}
    L ${right}, ${cy - r}
    A ${r},${r} 0 0,0 ${right},${cy + r}
    L ${right}, ${bottom}
    L ${left}, ${bottom}
    L ${left}, ${cy + r}
    A ${r},${r} 0 0,0 ${left},${cy - r}
    Z
  `.replace(/\s+/g, " ").trim();
};



export type TicketAnimationProps = Record<string, any>;

// Star SVG path scaled around origin (0,0) with radius 10
const starPath = "M 0,-10 L 3,-3 L 10,-3 L 5,2 L 7,9 L 0,5 L -7,9 L -5,2 L -10,-3 L -3,-3 Z";

interface TicketProps {
  id: string;
  w: number;
  h: number;
  ticketColor: string;
  borderColor: string;
  textColor: string;
  starsColor: string;
  text: string;
  fontFamily: string;
}

const Ticket: React.FC<TicketProps> = ({
  id,
  w,
  h,
  ticketColor,
  borderColor,
  textColor,
  starsColor,
  text,
  fontFamily,
}) => {
  const r = h * 0.125; // Proportional cutout radius
  const clipPathId = `ticket-clip-${id}`;
  const tearOffX = w * 0.76;

  // Render 7 stars centered symmetrically in the main ticket body
  const numStars = 7;
  const starAreaWidth = tearOffX - 80;
  const starPositions = Array.from({ length: numStars }).map((_, i) => {
    return 40 + (starAreaWidth / (numStars - 1)) * i;
  });

  const starScale = (h / 280) * 0.8;
  const topStarsY = h * 0.28;
  const bottomStarsY = h * 0.72;

  return (
    <svg
      width={w}
      height={h}
      viewBox={`0 0 ${w} ${h}`}
      style={{
        overflow: "visible",
        filter: "drop-shadow(0px 20px 40px rgba(0, 0, 0, 0.25))",
        transition: "none",
      }}
    >
      <defs>
        <clipPath id={clipPathId}>
          <path d={getTicketPath(w, h, r, 0)} />
        </clipPath>
      </defs>

      {/* Ticket Base Background */}
      <path d={getTicketPath(w, h, r, 0)} fill={ticketColor} />

      {/* Inner Concentric Border Line */}
      <path
        d={getTicketPath(w, h, r, 11)}
        fill="none"
        stroke={borderColor}
        strokeWidth={3}
      />

      {/* Ticket Tear-off Dashed Line */}
      <line
        x1={tearOffX}
        y1={12}
        x2={tearOffX}
        y2={h - 12}
        stroke={borderColor}
        strokeWidth={3}
        strokeDasharray="8 8"
        opacity={0.8}
      />

      {/* Diagonal Glare Overlay */}
      <path
        d={`M ${w * 0.45} 0 L ${w * 0.8} 0 L ${w * 0.5} ${h} L ${w * 0.15} ${h} Z`}
        fill="#ffffff"
        opacity={0.08}
        clipPath={`url(#${clipPathId})`}
      />

      {/* Upper Star Row */}
      {starPositions.map((x, i) => (
        <g key={`top-${i}`} transform={`translate(${x}, ${topStarsY}) scale(${starScale})`}>
          <path d={starPath} fill={starsColor} />
        </g>
      ))}

      {/* Brand Ticket Text */}
      <text
        x={tearOffX / 2}
        y={h * 0.53}
        fill={textColor}
        fontFamily={fontFamily}
        fontWeight="bold"
        fontSize={h * 0.24}
        textAnchor="middle"
        dominantBaseline="central"
        letterSpacing={1}
      >
        {text}
      </text>

      {/* Lower Star Row */}
      {starPositions.map((x, i) => (
        <g key={`bottom-${i}`} transform={`translate(${x}, ${bottomStarsY}) scale(${starScale})`}>
          <path d={starPath} fill={starsColor} />
        </g>
      ))}
    </svg>
  );
};

export const TicketAnimation: React.FC<TicketAnimationProps> = ({
  backgroundColor = "#121214",
  transparentBackground = true,
  durationInSeconds = 6,
  ticketText = "Malloy Studio",
  ticketColorFront = "#f6b97b",
  ticketColorBack = "#eb9c53",
  borderColorFront = "#e89f58",
  borderColorBack = "#df8c3b",
  textColorFront = "#5c371c",
  textColorBack = "#5c371c",
  starsColorFront = "#5c371c",
  starsColorBack = "#5c371c",
  ticketScale = 1.1,
  staggerDelay = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dynamic ticket dimensions based on responsive canvas sizing
  const ticketWidth = width * 0.76;
  const ticketHeight = ticketWidth / 2.14; // Maintains original aspect ratio

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Spring physics configurations for entrance animation
  const backSpring = spring({
    frame: frame - 12,
    fps,
    config: { damping: 13, mass: 0.8, stiffness: 85 },
  });

  const frontSpring = spring({
    frame: frame - (12 + staggerDelay),
    fps,
    config: { damping: 11, mass: 0.9, stiffness: 80 },
  });

  // Dynamic hover floating mechanics to breathe organic motion into the tickets
  const backHoverY = Math.sin(frame * 0.04) * 8;
  const backHoverX = Math.cos(frame * 0.035) * 6;
  const backHoverRot = Math.cos(frame * 0.045) * 0.5;

  const frontHoverY = Math.cos(frame * 0.045) * 10;
  const frontHoverX = Math.sin(frame * 0.04) * 8;
  const frontHoverRot = Math.sin(frame * 0.05) * 0.7;

  // Back Ticket animation values
  const backScaleVal = interpolate(backSpring, [0, 1], [0.4, ticketScale], {
    extrapolateRight: "clamp",
  });
  const backTx = interpolate(backSpring, [0, 1], [-width * 0.1, 0], {
    extrapolateRight: "clamp",
  }) + backHoverX;
  const backTy = interpolate(backSpring, [0, 1], [height * 0.25, 0], {
    extrapolateRight: "clamp",
  }) + backHoverY;
  const backRotate = interpolate(backSpring, [0, 1], [-45, -11], {
    extrapolateRight: "clamp",
  }) + backHoverRot;
  const backOpacity = interpolate(frame, [12, 22], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Front Ticket animation values
  const frontScaleVal = interpolate(frontSpring, [0, 1], [0.4, ticketScale], {
    extrapolateRight: "clamp",
  });
  const frontTx = interpolate(frontSpring, [0, 1], [width * 0.1, 0], {
    extrapolateRight: "clamp",
  }) + frontHoverX;
  const frontTy = interpolate(frontSpring, [0, 1], [height * 0.25, 0], {
    extrapolateRight: "clamp",
  }) + frontHoverY;
  const frontRotate = interpolate(frontSpring, [0, 1], [30, 0], {
    extrapolateRight: "clamp",
  }) + frontHoverRot;
  const frontOpacity = interpolate(
    frame,
    [12 + staggerDelay, 12 + staggerDelay + 10],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Position Styling
  const backStyle: React.CSSProperties = {
    position: "absolute",
    width: ticketWidth,
    height: ticketHeight,
    left: width / 2 - ticketWidth / 2,
    top: height / 2 - ticketHeight / 2 - height * 0.06,
    transform: `scale(${backScaleVal}) translate(${backTx}px, ${backTy}px) rotate(${backRotate}deg)`,
    opacity: backOpacity,
    transformOrigin: "center center",
    transition: "none",
  };

  const frontStyle: React.CSSProperties = {
    position: "absolute",
    width: ticketWidth,
    height: ticketHeight,
    left: width / 2 - ticketWidth / 2,
    top: height / 2 - ticketHeight / 2 + height * 0.06,
    transform: `scale(${frontScaleVal}) translate(${frontTx}px, ${frontTy}px) rotate(${frontRotate}deg)`,
    opacity: frontOpacity,
    transformOrigin: "center center",
    transition: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Back Ticket */}
      <div style={backStyle}>
        <Ticket
          id="back"
          w={ticketWidth}
          h={ticketHeight}
          ticketColor={ticketColorBack}
          borderColor={borderColorBack}
          textColor={textColorBack}
          starsColor={starsColorBack}
          text={ticketText}
          fontFamily={oswaldFamily}
        />
      </div>

      {/* Front Ticket */}
      <div style={frontStyle}>
        <Ticket
          id="front"
          w={ticketWidth}
          h={ticketHeight}
          ticketColor={ticketColorFront}
          borderColor={borderColorFront}
          textColor={textColorFront}
          starsColor={starsColorFront}
          text={ticketText}
          fontFamily={oswaldFamily}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TicketAnimation;